contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    uint public beforeBal;

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        require(amount > 0, "amount must be positive");

        uint balBefore = address(c).balance;
        // Since msg.sender is this test contract and it deployed c, caller is owner.
        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint balAfter = address(c).balance;

        assert(balBefore - balAfter == amount);
    }

    receive() external payable {}
}

